import{_ as t,o as a,c as r,a3 as i}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"Flow-Rate Logistics Blueprint Library","description":"","frontmatter":{"translationSource":{"title":"流量物流蓝图库","archivedAt":"2026-10-29","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=iGsD2TAazUlL90onJtfkps","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/flow-rate-logistics-blueprint-library"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/flow-rate-logistics-blueprint-library"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/flow-rate-logistics-blueprint-library"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/flow-rate-logistics-blueprint-library"}]]},"headers":[],"relativePath":"flow-rate-logistics-blueprint-library.md","filePath":"logistics/src/page-iGsD2TAazUlL90onJtfkps.md"}'),s={name:"flow-rate-logistics-blueprint-library.md"};function o(n,e,l,p,u,d){return a(),r("div",null,[...e[0]||(e[0]=[i('<div class="logistics-content"><span class="logistics-source-anchor" id="流量物流蓝图库" aria-hidden="true"></span><h1 id="flow-rate-logistics-blueprint-library" tabindex="-1">Flow-Rate Logistics Blueprint Library <a class="header-anchor" href="#flow-rate-logistics-blueprint-library" aria-label="Permalink to &quot;Flow-Rate Logistics Blueprint Library&quot;">​</a></h1><blockquote><p>Source page ID: <code>iGsD2TAazUlL90onJtfkps</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=iGsD2TAazUlL90onJtfkps" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><details><summary>Start with common fractions</summary><p>Denominators such as 2 3 4 5 6 8 9 10 12.</p><p>No need to bother with the very simple ones, like 2,3,6.</p><p>It wouldn&#39;t hurt to make them anyway. Someone might actually need 1/6.</p><p>Then we can just enumerate them exhaustively.</p></details><details><summary>Should we consider lag-based ones?</summary><p>Probably not, but we should check whether bugs affect the structures found by the search.</p><p>What is the case for lag-based ones?</p><p>Some have excellent footprints.</p><p>The same structure behaves differently with belts and pipes, and can only construct certain denominators. It&#39;s a bug that might be exploitable, but unexpected effects would be horrible.</p><p>I think anything usable can be included.</p><p>Damn damn damn damn, sudden enlightenment. No, sudden bewilderment.</p></details><details><summary>Selection criteria</summary><p>I think we could add some filters.<br> Pipes and belts also need separate categories.</p><p>Zirunwang: 10-12 02:27:29<br> Blueprint group<br> Name<br> Blueprint code<br> Account holding it (hidden)<br> Description<br> tags<br> Image<br> Notes</p><p>Do we need to include transposes of rate-limiting structures?</p><p>Probably not; the result is the same anyway (</p><p>Normally, yes, but warm-up time and the effects of logistics bugs differ.</p><p>Pareto frontier.</p><p>If a structure excels at nothing on its own, but can be used as a substructure to construct a better large structure, does it need its own entry?</p><p>Being usable to construct a better large structure is an advantage in itself.</p><p>As a substructure, its number of ports matters, but more unused ports mean lower utilization.</p><p>I feel we should go end to end; better if users don&#39;t have to think.</p></details><details><summary>Should we define a blueprint data format?—Closed</summary><p>You mean using an encoding rather than png?</p><p>Yes, that is what I had in mind. Lossless blueprints, and a smaller actual file size too.</p><p>Then we really could borrow IndustrialPlanner&#39;s format, or even generate it there and export it into the format Yituliu uses.</p><p>The simulator gave me its core rendering code. Yituliu plans to use it for drawing, so the two should integrate seamlessly later.</p><p>That means I no longer have to get AI to analyze the entire simulator repository to find this thing and imitate it. They&#39;ll also let me know if the relevant features are updated later.</p><p>The simulator&#39;s author is already preparing an embeddable rendering module for third parties. If all goes well, Yituliu could even call it directly.</p><p>It would be even better if the simulator&#39;s author opened up json import.</p><p>Doesn&#39;t it already have that?</p><p>It does. Look up the data format yourself.</p><p>Or make a few simple little things and export them to see.</p></details><details><summary>Provide output sequences? Is warm-up time necessary?—Closed</summary><p>I think we should provide output sequences, including starts from empty and from full.</p><p>Can warm-up time and uniformity be obtained from the output sequence?</p><p>Mainly uniformity, I think.</p><p>We might not be able to provide an output sequence. The same structure need not give the same result with different initial conditions.</p><p>We can&#39;t enumerate every Splitter&#39;s and Converger&#39;s initial state, can we?</p><p>Oh damn, you&#39;re right.</p></details><p>Actually, we should start by making small fractions.</p><p>Then these questions will disappear on their own.</p><p><strong>Current requirements</strong></p><p>x/6,x/7, x/11, x/30 (excluding x/5,x/6), 1/x rate limiters</p><p>1:4 splitting, 1:6 splitting, 1:1:3 splitting</p><p>325/799 rate limiter</p><p><a href="/endfield-skydoc/logistics/src/assets/attachments/result.txt-f1b983b7327ad752.txt">Attachment: result.txt</a></p><blockquote><p>Original: result.txt; size: 7324; objKey: <code>d6d70bfc7f7949e3a6eca412fc7f542b</code>; local status: downloaded.</p></blockquote></div>',1)])])}const m=t(s,[["render",o]]);export{h as __pageData,m as default};
